"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { createGlyphMesh, glyphGrid, normalizeGlyphOptions, type GlyphForm, type GlyphTone } from "@/lib/cojeev/glyph-mesh";
import { sculptureGeometry, type SculptureGeometryInput } from "@/lib/cojeev/sculpture-geometry";
import { rasterizeSculpture, sculptureCharacters, sculptureGrid, sculptureNumber, sculpturePrint, sculpturePrintPath, type GlyphSet, type PrintOptions } from "@/lib/cojeev/sculpture-raster";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";

export type { GlyphForm, GlyphTone, GlyphSet, SculptureGeometryInput };
export { loadSculptureFile, sculptureFromGLB, sculptureFromSVG } from "@/lib/cojeev/sculpture-loaders";
export { sculptureFromPixels, sculptureGeometry } from "@/lib/cojeev/sculpture-geometry";
export type SculptureCommonProps = Omit<React.ComponentPropsWithoutRef<"div">, "children"> & {
  form?: GlyphForm; tone?: GlyphTone;
  /** Immutable triangle geometry. Centered and fitted to a unit sphere; invalid geometry exposes an error. */
  geometry?: SculptureGeometryInput;
  speed?: number; turn?: number; pitch?: number; zoom?: number;
  pointerTracking?: boolean; paused?: boolean;
  onGeometryError?: (error: Error) => void;
};
export type GlyphSculptureProps = SculptureCommonProps & {
  /** Character-cell height in CSS pixels, bounded to 7–20. */
  cellSize?: number;
  glyphSet?: GlyphSet;
  /** Trace the silhouette with directional marks in the density set. */
  edgeMatching?: boolean;
};
type SurfaceOptions = { kind: "glyph" | "dither" | "ink"; cellSize?: number; glyphSet?: GlyphSet; edgeMatching?: boolean; grainSize?: number } & Omit<PrintOptions, "kind">;
type Configuration = SurfaceOptions & { run: boolean; visible: boolean; pointer: boolean; speed: number; turn: number; pitch: number; zoom: number };
type Control = { configure: (configuration: Configuration) => void };

/** Shared surface primitive: geometry, print treatment and motion have separate owners. */
export function SculptureSurface({ form = "bloom", tone = "rose", geometry, speed = 1, turn = 0, pitch = 0, zoom = 1, pointerTracking = false, paused = false, onGeometryError, className, surfaceOptions, ...props }: SculptureCommonProps & { surfaceOptions: SurfaceOptions }) {
  const host = React.useRef<HTMLDivElement>(null), canvas = React.useRef<HTMLCanvasElement>(null), control = React.useRef<Control | null>(null);
  const { enabled, inView } = useMotionVisibility(host);
  const safeForm: GlyphForm = form === "seed" || form === "pebble" ? form : "bloom";
  const safeTone: GlyphTone = ["ink", "rose", "moss", "sky"].includes(tone) ? tone : "rose";
  const { speed: pace, cellSize: size, turn: degrees } = normalizeGlyphOptions({ speed, cellSize: surfaceOptions.cellSize, turn });
  const tilt = sculptureNumber(pitch, 0, -80, 80), scale = sculptureNumber(zoom, 1, .6, 1.15), moving = enabled && inView && !paused && pace > 0;
  const { kind, glyphSet = "density", edgeMatching = true, pattern, treatment, grainSize, markSize, density, angle, relief } = surfaceOptions;
  const meshResult = React.useMemo(() => {
    try { return { mesh: geometry ? sculptureGeometry(geometry) : sculptureGeometry(createGlyphMesh(safeForm)), error: null }; }
    catch (error) { return { mesh: null, error: error instanceof Error ? error : new Error("The geometry could not be read.") }; }
  }, [geometry, safeForm]);
  const mesh = meshResult.mesh;
  React.useEffect(() => { if (meshResult.error) onGeometryError?.(meshResult.error); }, [meshResult.error, onGeometryError]);
  const configuration = React.useRef<Configuration>({ ...surfaceOptions, run: moving, visible: inView, pointer: pointerTracking, speed: pace, cellSize: size, turn: degrees, pitch: tilt, zoom: scale });
  const [renderer, setRenderer] = React.useState("pending");
  const still = React.useMemo(() => {
    if (!mesh) return null;
    const grid = kind === "glyph" ? glyphGrid(432, 324, 10.8) : sculptureGrid(384, 288, 4);
    const frame = rasterizeSculpture(mesh, grid, .35 + degrees * Math.PI / 180, -.2 + tilt * Math.PI / 180, scale);
    if (kind === "glyph") { const characters = sculptureCharacters(frame, glyphSet, edgeMatching), lines: string[] = []; for (let i = 0; i < characters.length; i += grid.columns) lines.push(characters.slice(i, i + grid.columns).join("")); return { text: lines.join("\n"), grid }; }
    return { path: sculpturePrintPath(sculpturePrint(frame, { kind, pattern, treatment, markSize, density, angle, relief }), grid.columns), grid };
  }, [mesh, kind, degrees, tilt, scale, glyphSet, edgeMatching, pattern, treatment, markSize, density, angle, relief]);

  React.useEffect(() => {
    configuration.current = { kind, glyphSet, edgeMatching, pattern, treatment, grainSize, markSize, density, angle, relief, run: moving, visible: inView, pointer: pointerTracking, speed: pace, cellSize: size, turn: degrees, pitch: tilt, zoom: scale };
    control.current?.configure(configuration.current);
  }, [kind, glyphSet, edgeMatching, pattern, treatment, grainSize, markSize, density, angle, relief, moving, inView, pointerTracking, pace, size, degrees, tilt, scale, safeTone]);

  React.useEffect(() => {
    const element = host.current, surface = canvas.current;
    if (!element || !surface || !mesh) return;
    let context: CanvasRenderingContext2D | null;
    try { context = surface.getContext("2d"); } catch { context = null; }
    if (!context) { setRenderer("fallback"); return; }
    let options = configuration.current, disposed = false, lost = false, frame = 0, last = 0, elapsed = 0, painted = false;
    let width = 1, height = 1, ratio = 1, pointerX = 0, pointerY = 0, tiltX = 0, tiltY = 0, ink = "#26282d";
    let grid = glyphGrid(width, height, options.cellSize ?? 10);
    const hover = window.matchMedia("(any-hover: hover) and (any-pointer: fine)");
    function cancel() { if (frame) cancelAnimationFrame(frame); frame = 0; last = 0; }
    function request() { if (!disposed && !lost && !frame && options.visible && !document.hidden) frame = requestAnimationFrame(draw); }
    function draw(now: number) {
      frame = 0;
      if (disposed || lost || !options.visible || document.hidden) return;
      if (options.run && last && now - last < 32) { request(); return; }
      if (options.run) { elapsed += (last ? Math.min(now - last, 70) : 0) / 1000 * options.speed; tiltX += (pointerX - tiltX) * .18; tiltY += (pointerY - tiltY) * .18; }
      last = now;
      const yaw = .35 + options.turn * Math.PI / 180 + Math.sin(elapsed * .42) * .4 + tiltX, pitch = -.2 + options.pitch * Math.PI / 180 + Math.sin(elapsed * .31) * .12 + tiltY;
      const result = rasterizeSculpture(mesh!, grid, yaw, pitch, options.zoom);
      surface!.dataset.sampling = result.sampling > 1 ? "adaptive" : "full";
      context!.setTransform(ratio, 0, 0, ratio, 0, 0); context!.clearRect(0, 0, width, height); context!.fillStyle = ink; context!.globalAlpha = 1;
      if (options.kind === "glyph") {
        const characters = sculptureCharacters(result, options.glyphSet, options.edgeMatching);
        context!.font = `600 ${grid.cellHeight * .94}px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace`; context!.textAlign = "center"; context!.textBaseline = "middle";
        for (let i = 0; i < characters.length; i++) if (characters[i] !== " ") context!.fillText(characters[i], (i % grid.columns + .5) * grid.cellWidth, (Math.floor(i / grid.columns) + .5) * grid.cellHeight);
      } else {
        const marks = sculpturePrint(result, { ...options, kind: options.kind });
        for (let i = 0; i < marks.length;) {
          if (!marks[i]) { i++; continue; }
          const x = i % grid.columns, y = Math.floor(i / grid.columns); let count = 1;
          while (x + count < grid.columns && marks[i + count]) count++;
          context!.fillRect(x * grid.cellWidth, y * grid.cellHeight, count * grid.cellWidth + .25, grid.cellHeight + .25); i += count;
        }
      }
      if (!painted) { painted = true; setRenderer("canvas2d"); }
      if (options.run) request();
    }
    function resize() {
      const rect = element!.getBoundingClientRect(); width = Math.max(1, rect.width); height = Math.max(1, rect.height);
      ratio = Math.min(2, window.devicePixelRatio || 1, 2048 / Math.max(width, height), Math.sqrt(1500000 / (width * height)));
      const backingWidth = Math.max(1, Math.floor(width * ratio)), backingHeight = Math.max(1, Math.floor(height * ratio));
      if (surface!.width !== backingWidth || surface!.height !== backingHeight) { surface!.width = backingWidth; surface!.height = backingHeight; }
      grid = options.kind === "glyph" ? glyphGrid(width, height, options.cellSize ?? 10) : sculptureGrid(width, height, options.kind === "dither" ? sculptureNumber(options.grainSize, 3, 1.5, 9) : 1.5);
      repaint();
    }
    function repaint() { ink = getComputedStyle(element!).color; request(); }
    const instance: Control = { configure(next) { options = next; if (!options.pointer || !options.run) { pointerX = 0; pointerY = 0; } cancel(); resize(); } };
    control.current = instance;
    const pointer = (event: PointerEvent) => {
      if (!options.run || !options.pointer || !hover.matches || event.pointerType === "touch") return;
      const rect = element.getBoundingClientRect(), x = (event.clientX - rect.left) / rect.width, y = (event.clientY - rect.top) / rect.height, inside = x >= 0 && x <= 1 && y >= 0 && y <= 1;
      pointerX = inside ? (x * 2 - 1) * .3 : 0; pointerY = inside ? (y * 2 - 1) * .2 : 0;
    };
    const visibility = () => { cancel(); request(); }, onLost = (event: Event) => { event.preventDefault(); lost = true; cancel(); setRenderer("fallback"); }, onRestored = () => { lost = false; painted = false; resize(); };
    const resizeObserver = new ResizeObserver(resize); resizeObserver.observe(element);
    const appearance = new MutationObserver(repaint);
    for (let ancestor: Element | null = element; ancestor; ancestor = ancestor.parentElement) appearance.observe(ancestor, { attributes: true, attributeFilter: ["class", "style", "data-mode", "data-tone"] });
    window.addEventListener("pointermove", pointer, { passive: true }); window.addEventListener("resize", resize); window.addEventListener("cojeev:appearancechange", repaint); document.addEventListener("visibilitychange", visibility);
    surface.addEventListener("contextlost", onLost); surface.addEventListener("contextrestored", onRestored); resize();
    return () => {
      disposed = true; cancel(); if (control.current === instance) control.current = null;
      resizeObserver.disconnect(); appearance.disconnect(); window.removeEventListener("pointermove", pointer); window.removeEventListener("resize", resize); window.removeEventListener("cojeev:appearancechange", repaint); document.removeEventListener("visibilitychange", visibility);
      surface.removeEventListener("contextlost", onLost); surface.removeEventListener("contextrestored", onRestored); context!.clearRect(0, 0, surface.width, surface.height); surface.width = 1; surface.height = 1;
    };
  }, [mesh]);

  return <div {...props} ref={host} className={cn("v-sculpture-surface", `v-${kind}-sculpture`, className)} data-slot={`${kind}-sculpture`} data-form={geometry ? "custom" : safeForm} data-tone={safeTone} data-renderer={meshResult.error ? "error" : renderer} data-moving={moving && renderer === "canvas2d" && mesh ? "true" : "false"} aria-hidden={meshResult.error ? undefined : true} inert={meshResult.error ? undefined : true} role={meshResult.error ? "status" : undefined}>
    {meshResult.error ? <span data-slot="sculpture-error">{meshResult.error.message}</span> : still && ("text" in still ? <pre data-slot="glyph-sculpture-still">{still.text}</pre> : <svg data-slot="sculpture-print-still" viewBox={`0 0 ${still.grid.columns} ${still.grid.rows}`}><path d={still.path} fill="currentColor" /></svg>)}
    <canvas ref={canvas} data-slot="glyph-sculpture-canvas" />
  </div>;
}

/** A decorative three-dimensional surface drawn with characters and optional contour marks. */
export function GlyphSculpture({ cellSize = 10, glyphSet = "density", edgeMatching = true, ...props }: GlyphSculptureProps) {
  const set = glyphSet === "digits" || glyphSet === "letters" ? glyphSet : "density";
  return <SculptureSurface {...props} surfaceOptions={{ kind: "glyph", cellSize, glyphSet: set, edgeMatching }} />;
}

import { rasterizeSculpture } from "@/lib/cojeev/sculpture-raster";
/** Original organic geometry and a small, dependency-free character-cell rasterizer. */
export type GlyphForm = "seed" | "bloom" | "pebble";
export type GlyphTone = "ink" | "rose" | "moss" | "sky";
export const GLYPH_RAMP = " .,:;=+*#%@";
type Vector = [number, number, number];
export type GlyphMesh = { positions: Float32Array; normals: Float32Array; triangles: Uint16Array };
export type GlyphGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
const bounded = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;

export function normalizeGlyphOptions({ speed, cellSize, turn }: { speed?: number; cellSize?: number; turn?: number } = {}) {
  return { speed: bounded(speed, 1, 0, 3), cellSize: bounded(cellSize, 10, 7, 20), turn: bounded(turn, 0, -180, 180) };
}

export function glyphGrid(width: number, height: number, cellSize: number): GlyphGrid {
  width = bounded(width, 1, 1, 20000); height = bounded(height, 1, 1, 20000);
  const size = Math.max(bounded(cellSize, 10, 7, 20), width / (140 * .62), height / 90);
  const columns = Math.max(1, Math.min(140, Math.floor(width / (size * .62))));
  const rows = Math.max(1, Math.min(90, Math.floor(height / size)));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

function surface(form: GlyphForm, longitude: number, latitude: number): Vector {
  const ring = Math.sin(latitude), height = Math.cos(latitude);
  const x = Math.cos(longitude), z = Math.sin(longitude);
  if (form === "seed") return [.69 * ring * x * (1 + .2 * height), 1.08 * height, .5 * ring * z * (1 - .18 * height)];
  if (form === "bloom") {
    // A soft five-lobed cushion, with a shallow dimple at the center of each face.
    const radius = .83 + .19 * Math.cos(5 * longitude);
    return [radius * ring * x, radius * ring * z, .44 * height * (1 - .28 * Math.exp(-ring * ring * 12))];
  }
  const radius = 1 + .09 * Math.cos(3 * longitude + .3) * ring;
  return [.94 * ring * x * radius, .79 * height + .05 * ring * Math.sin(2 * longitude), .66 * ring * z * radius];
}

function unit(x: number, y: number, z: number): Vector {
  const length = Math.hypot(x, y, z) || 1;
  return [x / length, y / length, z / length];
}

export function createGlyphMesh(form: GlyphForm): GlyphMesh {
  const around = 64, vertical = 32;
  const positions = new Float32Array((around + 1) * (vertical + 1) * 3);
  const normals = new Float32Array(positions.length);
  const triangles: number[] = [];
  for (let row = 0; row <= vertical; row++) for (let column = 0; column <= around; column++) {
    const longitude = column / around * Math.PI * 2, latitude = row / vertical * Math.PI;
    const index = (row * (around + 1) + column) * 3;
    const point = surface(form, longitude, latitude);
    positions.set(point, index);
    const u0 = surface(form, longitude - .001, latitude), u1 = surface(form, longitude + .001, latitude);
    const v0 = surface(form, longitude, latitude - .001), v1 = surface(form, longitude, latitude + .001);
    const u = u1.map((value, i) => value - u0[i]), v = v1.map((value, i) => value - v0[i]);
    let normal = unit(u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]);
    if (row === 0 || row === vertical) normal = unit(...point);
    if (normal.reduce((sum, value, i) => sum + value * point[i], 0) < 0) normal = normal.map(value => -value) as Vector;
    normals.set(normal, index);
    if (row < vertical && column < around) {
      const a = row * (around + 1) + column, b = a + around + 1;
      triangles.push(a, b, a + 1, a + 1, b, b + 1);
    }
  }
  return { positions, normals, triangles: new Uint16Array(triangles) };
}

/** Compatibility density-grid API backed by the shared depth-tested surface. */
export function rasterizeGlyphs(mesh: GlyphMesh, grid: GlyphGrid, yaw = .35, pitch = -.2): Uint8Array {
  const frame = rasterizeSculpture(mesh, grid, yaw, pitch), cells = new Uint8Array(frame.coverage.length);
  for (let i = 0; i < cells.length; i++) if (frame.coverage[i]) cells[i] = Math.max(1, Math.min(GLYPH_RAMP.length - 1, Math.round(frame.light[i] * (GLYPH_RAMP.length - 2)) + 1));
  return cells;
}

export function glyphText(cells: Uint8Array, columns: number): string {
  const lines: string[] = [];
  for (let i = 0; i < cells.length; i += columns) lines.push(Array.from(cells.subarray(i, i + columns), value => GLYPH_RAMP[value]).join(""));
  return lines.join("\n");
}

import type { SculptureGeometry } from "@/lib/cojeev/sculpture-geometry";

export type SculptureGrid = { columns: number; rows: number; cellWidth: number; cellHeight: number; width: number; height: number };
export type SculptureFrame = { grid: SculptureGrid; coverage: Uint8Array; light: Float32Array; depth: Float32Array; sampling: number };
export const sculptureNumber = (value: number | undefined, fallback: number, min: number, max: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value!)) : fallback;
export function sculptureGrid(width: number, height: number, step = 2): SculptureGrid {
  width = sculptureNumber(width, 1, 1, 20000); height = sculptureNumber(height, 1, 1, 20000);
  step = Math.max(sculptureNumber(step, 2, 1.5, 12), width / 280, height / 220);
  const columns = Math.max(1, Math.floor(width / step)), rows = Math.max(1, Math.floor(height / step));
  return { columns, rows, cellWidth: width / columns, cellHeight: height / rows, width, height };
}

/** Original orthographic depth pass. The same surface supplies glyphs, print dots and engraved lines. */
export function rasterizeSculpture(mesh: SculptureGeometry, grid: SculptureGrid, yaw = .35, pitch = -.2, zoom = 1): SculptureFrame {
  const { columns, rows, cellWidth, cellHeight, width, height } = grid;
  const coverage = new Uint8Array(columns * rows), depth = new Float32Array(coverage.length).fill(-Infinity), light = new Float32Array(coverage.length);
  const projected = new Float32Array(mesh.positions.length / 3 * 4), cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch);
  const angle = -.14, cz = Math.cos(angle), sz = Math.sin(angle), scale = Math.min(width, height) * .39 * sculptureNumber(zoom, 1, .6, 1.15);
  function rotate(x: number, y: number, z: number) { const a = cy * x + sy * z, b = -sy * x + cy * z, c = cx * y - sx * b; return [cz * a - sz * c, sz * a + cz * c, sx * y + cx * b]; }
  for (let i = 0, out = 0; i < mesh.positions.length; i += 3, out += 4) {
    const p = rotate(mesh.positions[i], mesh.positions[i + 1], mesh.positions[i + 2]), n = rotate(mesh.normals[i], mesh.normals[i + 1], mesh.normals[i + 2]);
    projected[out] = columns / 2 + p[0] * scale / cellWidth; projected[out + 1] = rows / 2 - p[1] * scale / cellHeight; projected[out + 2] = p[2];
    projected[out + 3] = Math.min(1, .12 + .8 * Math.max(0, n[0] * -.42 + n[1] * .58 + n[2] * .69) + .12 * Math.abs(n[2]));
  }
  // Vertex/triangle limits alone cannot bound overlapping triangle work. Estimate
  // clipped coverage first, then lower sampling before any expensive raster pass.
  let work = 0;
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const left = Math.max(0, Math.floor(Math.min(projected[a], projected[b], projected[c]))), right = Math.min(columns - 1, Math.ceil(Math.max(projected[a], projected[b], projected[c])));
    const top = Math.max(0, Math.floor(Math.min(projected[a + 1], projected[b + 1], projected[c + 1]))), bottom = Math.min(rows - 1, Math.ceil(Math.max(projected[a + 1], projected[b + 1], projected[c + 1])));
    work += Math.max(0, right - left + 1) * Math.max(0, bottom - top + 1);
  }
  if (work > 350000 && (columns > 1 || rows > 1)) {
    const factor = Math.sqrt(work / 350000) * 1.15, lowColumns = Math.max(1, Math.floor(columns / factor)), lowRows = Math.max(1, Math.floor(rows / factor));
    const low = rasterizeSculpture(mesh, { ...grid, columns: lowColumns, rows: lowRows, cellWidth: width / lowColumns, cellHeight: height / lowRows }, yaw, pitch, zoom);
    for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
      const at = Math.min(lowRows - 1, Math.floor(y / rows * lowRows)) * lowColumns + Math.min(lowColumns - 1, Math.floor(x / columns * lowColumns)), i = y * columns + x;
      coverage[i] = low.coverage[at]; light[i] = low.light[at]; depth[i] = low.depth[at];
    }
    return { grid, coverage, depth, light, sampling: Math.max(columns / lowColumns, rows / lowRows) * low.sampling };
  }
  for (let i = 0; i < mesh.triangles.length; i += 3) {
    const a = mesh.triangles[i] * 4, b = mesh.triangles[i + 1] * 4, c = mesh.triangles[i + 2] * 4;
    const ax = projected[a], ay = projected[a + 1], bx = projected[b], by = projected[b + 1], cxp = projected[c], cyp = projected[c + 1];
    const denominator = (by - cyp) * (ax - cxp) + (cxp - bx) * (ay - cyp);
    if (Math.abs(denominator) < 1e-7) continue;
    const left = Math.max(0, Math.floor(Math.min(ax, bx, cxp))), right = Math.min(columns - 1, Math.ceil(Math.max(ax, bx, cxp)));
    const top = Math.max(0, Math.floor(Math.min(ay, by, cyp))), bottom = Math.min(rows - 1, Math.ceil(Math.max(ay, by, cyp)));
    for (let y = top; y <= bottom; y++) for (let x = left; x <= right; x++) {
      const wa = ((by - cyp) * (x + .5 - cxp) + (cxp - bx) * (y + .5 - cyp)) / denominator, wb = ((cyp - ay) * (x + .5 - cxp) + (ax - cxp) * (y + .5 - cyp)) / denominator, wc = 1 - wa - wb;
      if (wa < -.001 || wb < -.001 || wc < -.001) continue;
      const z = wa * projected[a + 2] + wb * projected[b + 2] + wc * projected[c + 2], index = y * columns + x;
      if (z <= depth[index]) continue;
      depth[index] = z; coverage[index] = 1; light[index] = wa * projected[a + 3] + wb * projected[b + 3] + wc * projected[c + 3];
    }
  }
  return { grid, coverage, depth, light, sampling: 1 };
}

export type DitherPattern = "ordered" | "halftone" | "diffusion" | "stipple";
export type InkTreatment = "hatch" | "crosshatch" | "contour";
export type PrintOptions = { kind: "dither" | "ink"; pattern?: DitherPattern; treatment?: InkTreatment; markSize?: number; density?: number; angle?: number; relief?: number };
const bayer = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const noise = (x: number, y: number) => { const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return n - Math.floor(n); };
const fract = (value: number) => value - Math.floor(value);
export function sculpturePrint(frame: SculptureFrame, options: PrintOptions): Uint8Array {
  const { grid, coverage, light, depth } = frame, { columns, rows, cellWidth, cellHeight } = grid, marks = new Uint8Array(coverage.length);
  const density = sculptureNumber(options.density, 1, .5, 1.6), spacing = sculptureNumber(options.markSize, 8, 4, 16), angle = sculptureNumber(options.angle, -25, -180, 180) * Math.PI / 180, relief = sculptureNumber(options.relief, .55, 0, 1);
  const errors = options.pattern === "diffusion" ? new Float32Array(coverage.length) : undefined;
  for (let y = 0; y < rows; y++) for (let x = 0; x < columns; x++) {
    const i = y * columns + x;
    if (!coverage[i]) continue;
    const shade = Math.max(.06, Math.min(.98, (.18 + (1 - light[i]) * .85) * density));
    if (options.kind === "dither") {
      if (errors) {
        const value = shade + errors[i], hit = value >= .5 ? 1 : 0, error = value - hit;
        marks[i] = hit * 255;
        if (x + 1 < columns) errors[i + 1] += error * 7 / 16;
        if (y + 1 < rows) { if (x) errors[i + columns - 1] += error * 3 / 16; errors[i + columns] += error * 5 / 16; if (x + 1 < columns) errors[i + columns + 1] += error / 16; }
      } else {
        const threshold = options.pattern === "stipple" ? noise(x, y) : options.pattern === "halftone" ? Math.hypot(fract(x / 5) - .5, fract(y / 5) - .5) * 1.42 : (bayer[(y % 4) * 4 + x % 4] + .5) / 16;
        marks[i] = shade > threshold ? 255 : 0;
      }
    } else {
